    const n = this.#host.physical();
    const presence = this.#presence;

    this.#kind = kind;
    this.#alloc(this.#capacity);
    for (let p = 0; p < n; p++) {
      const gone = presence !== null && presence.get(p) === 0;
      // Multi columns must still be pushed for absent rows so the offset table
      // stays dense; every other kind can be left at its filler.
      if (gone && kind !== 'multi') continue;
      this.#writeValue(p, gone ? null : decodeFrom(old, p));
    }
