  /**
   * The active session, or null.
   * @type {{ mode: 'cell'|'row', key: string, row: Row, colId: string|null,
   *          cells: Map<string, { original: unknown, value: unknown, dirty: boolean,
   *                               error: string|null }> }|null}
   */
