/**
 * A running ingest. Created by {@link ingest}; exposed so the stream source can
 * drive it a slice at a time against its own scheduler (§4.4, §5.11).
 */
 class Ingest {
  /** @type {unknown[]} the rows being ingested */
  #rows;

  /** @type {ColumnPlan[]} per-column plans, in schema order */
  #plans = [];

  /** @type {ColumnStore|null} the store being filled */
  #store = null;

  /** @type {{ readers: Map<string, Function>, reset(): void }} resolved readers */
  #readers;

  /** @type {number} rows written so far */
  #cursor = 0;

  /** @type {object} resolved options */
  #opts;

  /** @type {boolean} set once every row is written and the final decisions are applied */
  #done = false;

  /** @type {boolean} set by `cancel()` or an aborted signal */
  #cancelled = false;

  /** @type {number} wall-clock milliseconds spent in slices */
  #elapsed = 0;

  /** @type {boolean} whether the store will columnarise for this dataset (§5.12) */
  #columnar;

  /**
   * @param {unknown[]} rows the caller's row objects
   * @param {{ columns?: IngestColumn[], computed?: ComputedInjection|null, context?: unknown }} [plan]
   *   the columns to store and the injected computed graph
   * @param {{ chunkMs?: number, chunkRows?: number, sampleSize?: number,
   *           dictionaryRatio?: number, columnarBelow?: number, initialCapacity?: number,
   *           scheduler?: { frame(fn: Function): unknown }, signal?: AbortSignal,
   *           onProgress?: (p: { loaded: number, total: number }) => void }} [opts]
   *   ingest tuning; see {@link INGEST_DEFAULTS}
   */
  constructor(rows, plan = {}, opts = {}) {
    this.#rows = Array.isArray(rows) ? rows : Array.from(rows || []);
    this.#opts = { ...INGEST_DEFAULTS, ...opts };
    const columns = plan.columns ?? [];
    this.#readers = createReaders(columns, plan.computed ?? null, plan.context);
    this.#columnar = this.#rows.length >= this.#opts.columnarBelow;
    this.#planColumns(columns, plan.computed ?? null);
    this.#store = new ColumnStore(this.#plans.map((p) => ({
      id: p.spec.id,
      kind: p.kind,
      nullable: p.nullable,
      read: p.read,
      dictionary: p.spec.dictionary,
    })), {
      initialCapacity: this.#opts.initialCapacity,
      columnarBelow: this.#opts.columnarBelow,
    });
  }

  /**
   * The store being filled. Usable before ingest finishes: rows already written
   * are readable, which is what lets the grid render during a load (§5.11).
   * @returns {ColumnStore} the store
   */
  get store() { return this.#store; }

  /**
   * Is every row written and every decision settled?
   * @returns {boolean} true when finished or cancelled
   */
  get done() { return this.#done || this.#cancelled; }

  /**
   * Rows written so far.
   * @returns {number} the ingest cursor
   */
  get progress() { return this.#cursor; }

  /**
   * Run one frame's worth of work: chunks are written until the frame budget is
   * spent, then control returns to the caller (§5.11).
   * @returns {boolean} true when there is more work to do
   */
  slice() {
    if (this.done) return false;
    if (this.#opts.signal?.aborted) { this.#cancelled = true; return false; }
    const started = now();
    const { chunkMs, chunkRows } = this.#opts;
    const total = this.#rows.length;

    do {
      const end = Math.min(this.#cursor + chunkRows, total);
      this.#store.append(this.#rows.slice(this.#cursor, end));
      this.#measure(this.#cursor, end);
      this.#cursor = end;
      this.#readers.reset();
      this.#reviewCardinality(false);
    } while (this.#cursor < total && now() - started < chunkMs);

    this.#elapsed += now() - started;
    this.#opts.onProgress?.({ loaded: this.#cursor, total });
    if (this.#cursor >= total) {
      this.#reviewCardinality(true);
      this.#done = true;
      return false;
    }
    return true;
  }

  /**
   * Stop ingest where it is. The store keeps the rows already written.
   * @returns {void}
   */
  cancel() { this.#cancelled = true; }

  /**
   * The finished result.
   * @returns {{ store: ColumnStore, schema: object[], decisions: IngestDecision[],
   *             count: number, elapsed: number, cancelled: boolean }} the ingest result
   */
  result() {
    return {
      store: this.#store,
      schema: this.#plans.map((p) => ({
        id: p.spec.id, kind: p.kind, nullable: p.nullable, read: p.read,
        dictionary: p.spec.dictionary,
      })),
      decisions: this.#plans.map((p) => ({
        id: p.spec.id,
        kind: p.kind,
        nullable: p.nullable,
        inferred: p.inferred,
        distinct: p.candidate || p.change ? this.#distinctOf(p) : null,
        change: p.change,
        reason: p.reason,
      })),
      count: this.#store.count,
      elapsed: this.#elapsed,
      cancelled: this.#cancelled,
    };
  }

  /* ---------------------------------------------------------------- */
  /* Internals                                                        */
  /* ---------------------------------------------------------------- */

  /**
   * Decide a provisional backing per column from a sample of the first N rows
   * (§8.2 inference, §5.4 cardinality), so writing can begin without a full
   * pass.
   * @param {IngestColumn[]} columns the caller's column specs
   * @param {ComputedInjection|null} computed the injected graph
   * @returns {void}
   */
  #planColumns(columns, computed) {
    const rows = this.#rows;
    const sampleN = Math.min(this.#opts.sampleSize, rows.length);
    const ratio = this.#opts.dictionaryRatio;
    const pure = computed?.pure instanceof Set
      ? computed.pure
      : new Set(computed?.pure ?? computed?.order ?? []);

    for (const spec of columns) {
      if (!spec || !spec.id) continue;
      if (spec.computed && (spec.pure === false || (computed && !pure.has(spec.id)))) {
        // Impure computations are not a function of the stored data, so they
        // cannot be materialised (§5.12). The column layer re-evaluates them.
        warnOnce(`ingest.impure.${spec.id}`,
          `column "${spec.id}" is an impure computed column and is not materialised into the store`);
        continue;
      }
      const read = this.#readers.readers.get(spec.id)
        ?? (isFunction(spec.read) ? spec.read : pathGetter(spec.field || spec.id));
      const plan = new ColumnPlan(spec, read);

      if (spec.kind) {
        plan.kind = spec.kind;
        plan.reason = 'declared by the caller';
      } else if (spec.dictionary) {
        // A supplied value table means a lookup column: dictionary immediately,
        // with no cardinality measurement and no inference pass (§8.3).
        plan.kind = spec.multi ? 'multi' : 'dictionary';
        plan.reason = 'value table supplied (lookup column)';
      } else {
        const samples = [];
        for (let i = 0; i < sampleN && samples.length < this.#opts.sampleSize; i++) {
          const v = read(rows[i]);
          if (v !== null && v !== undefined) samples.push(v);
        }
        plan.inferred = true;
        const kind = inferKind(samples, { multi: spec.multi });
        if (kind === 'text') {
          const distinct = new Set(samples).size;
          plan.kind = decideText(distinct, samples.length, ratio);
          plan.candidate = this.#columnar;
          plan.reason = `sampled ${distinct} distinct in ${samples.length}`;
        } else {
          plan.kind = kind;
          plan.reason = `inferred from ${samples.length} sampled values`;
          if (kind === 'object' && samples.length) {
            infoOnce(`ingest.mixed.${spec.id}`,
              `column "${spec.id}" holds mixed or unrecognised value types; storing as an object array. Declare a type to avoid this.`);
          }
        }
        if (plan.kind === 'object' && plan.candidate) plan.distinct = new Set(samples);
      }
      this.#plans.push(plan);
    }
  }

  /**
   * Track distinct values for columns whose dictionary decision is still open.
   * Dictionary-backed candidates get this for free from the dictionary's own
   * size; only demoted or provisionally-object candidates pay a second read.
   * @param {number} from first physical index in the chunk
   * @param {number} to one past the last physical index in the chunk
   * @returns {void}
   */
  #measure(from, to) {
    const rows = this.#rows;
    for (const plan of this.#plans) {
      if (!plan.candidate || !plan.distinct) continue;
      const set = plan.distinct;
      for (let i = from; i < to; i++) {
        const v = plan.read(rows[i]);
        if (v !== null && v !== undefined) set.add(v);
      }
    }
  }

  /**
   * Distinct count for a candidate column: the dictionary's size when it is
   * dictionary-backed, the tracked set otherwise.
   * @param {ColumnPlan} plan the column plan
   * @returns {number} distinct values seen so far
   */
  #distinctOf(plan) {
    if (plan.distinct) return plan.distinct.size;
    const handle = this.#store.column(plan.spec.id);
    return handle?.dict ? handle.dict.size : 0;
  }

  /**
   * Confirm or contradict the sampled dictionary decision (§5.4, §5.11).
   *
   * Demotion happens the moment the distinct count passes the threshold, which
   * is genuinely mid-ingest — the count only grows, so the verdict is final.
   * Promotion waits for the end of the pass, because a low count early proves
   * nothing. Either way physical indices do not move and codes are not
   * reassigned, so a permutation taken before the change stays valid (§5.14).
   *
   * @param {boolean} final true on the last call, when promotion is decided
   * @returns {void}
   */
  #reviewCardinality(final) {
    const ratio = this.#opts.dictionaryRatio;
    const total = this.#rows.length;
    for (const plan of this.#plans) {
      if (!plan.candidate) continue;
      const distinct = this.#distinctOf(plan);
      if (plan.kind === 'dictionary' && distinct >= ratio * total) {
        // Seed the tracking set from the dictionary we are about to abandon:
        // its values are exactly the distinct values seen so far.
        const handle = this.#store.column(plan.spec.id);
        plan.distinct = new Set(handle?.dict ? handle.dict.values() : []);
        this.#store.convert(plan.spec.id, 'object');
        plan.kind = 'object';
        plan.change = 'demoted';
        plan.reason = `${distinct} distinct values is at or above ${ratio * 100}% of ${total} rows`;
        continue;
      }
      if (plan.kind === 'object' && distinct >= ratio * total) {
        // The distinct count only grows, so this column can never qualify for
        // encoding. Settle it now and drop the tracking set, which would
        // otherwise grow to one entry per row on a genuinely unique column.
        plan.candidate = false;
        plan.distinct = null;
        plan.reason = `${distinct} distinct values is at or above ${ratio * 100}% of ${total} rows`;
        continue;
      }
      if (final && plan.kind === 'object' && distinct < ratio * total) {
        this.#store.convert(plan.spec.id, 'dictionary');
        plan.kind = 'dictionary';
        plan.change = plan.change === 'demoted' ? null : 'promoted';
        plan.reason = `${distinct} distinct values is below ${ratio * 100}% of ${total} rows`;
        plan.distinct = null;
      }
      if (final) plan.candidate = false;
    }
  }
}

/**
 * Ingest rows into a new `ColumnStore`, chunked to a frame budget (§5.11).
 *
 * @param {unknown[]} rows the caller's row objects, retained by reference (§5.9)
 * @param {{ columns?: IngestColumn[], computed?: ComputedInjection|null, context?: unknown }} [plan]
 *   the columns to store and the injected computed-value graph
 * @param {object} [opts] tuning; see {@link INGEST_DEFAULTS}. `scheduler.frame`
 *   defaults to `requestAnimationFrame` via `internal/util.js`
 * @returns {Promise<{ store: ColumnStore, schema: object[], decisions: IngestDecision[],
 *                     count: number, elapsed: number, cancelled: boolean }>} the result
 */
 async function ingest(rows, plan = {}, opts = {}) {
  const run = new Ingest(rows, plan, opts);
  const frame = opts.scheduler?.frame ?? nextFrame;
  while (run.slice()) {
    await new Promise((resolve) => { frame(resolve); });
  }
  return run.result();
}

/**
 * Ingest without yielding. For tests, for Worker-side loads where there is no
 * frame to protect (§5.13), and for datasets small enough that chunking is
 * noise (§5.12).
 * @param {unknown[]} rows the caller's row objects
 * @param {{ columns?: IngestColumn[], computed?: ComputedInjection|null, context?: unknown }} [plan]
 *   the columns to store and the injected computed-value graph
 * @param {object} [opts] tuning; see {@link INGEST_DEFAULTS}
 * @returns {{ store: ColumnStore, schema: object[], decisions: IngestDecision[],
 *             count: number, elapsed: number, cancelled: boolean }} the result
 */
 function ingestSync(rows, plan = {}, opts = {}) {
  const run = new Ingest(rows, plan, { ...opts, chunkMs: Infinity });
  while (run.slice());
  return run.result();
}

