    for (let r = -1; r <= 7; r++) {
      for (let c = -1; c <= 7; c++) {
        const inner = r >= 2 && r <= 4 && c >= 2 && c <= 4;
        const ring = (r === 0 || r === 6) && c >= 0 && c <= 6;
        const side = (c === 0 || c === 6) && r >= 0 && r <= 6;
        set(row + r, col + c, inner || ring || side ? 1 : 0);
      }
    }
