  /** @type {Document|null} */ doc = null;
  /** @type {Record<string, unknown>} */ props = {};
  /** @type {LookupApi|null} */ lookup = null;
  /** @type {boolean} */ popup = false;
  /** @type {HTMLElement|null} */ #root = null;
  /** @type {Popup|null} */ #popup = null;
  /** @type {boolean} */ #cancelled = false;
  /** @type {boolean} */ #stopping = false;
  /** @type {string|null} */ #message = null;
